#pragma once
// Disc file check (docs/SETUP.md "Disc file check", from LM's disc image check): every file of the
// player's disc (image or extracted folder) is compared (size, CRC-32) with the retail rev 1 disc's
// (tables src/setup/disc_files_<ID>.inc, generated by tools/gen_disc_files.py). Disc::open only
// verifies main.dol and the RELs; a damaged or modified game data file used to start and then
// crash in the game (a changed Layout/title_us.arc: "OSPanic TPL.c:25" at the title screen). The
// result is cached per disc (path + size / modification times) in <dataDir>/disc_check_<ID>.txt,
// so the files are read once.
#include "port/install.h"

#include <atomic>
#include <functional>
#include <optional>
#include <string>
#include <vector>

namespace setup {

struct DiscCheck {
    int files = 0;                 // retail files compared
    std::vector<std::string> bad;  // "<path> (missing|size|contents|unreadable)"
    bool accepted = false;         // the player chose to play with this disc anyway
    bool ok() const { return bad.empty(); }
    // "3 of 9055 game files differ from the retail disc: /a (contents), /b (size), ..."
    std::string summary(size_t maxNames = 4) const;
};

// The cached result for this disc, if it is still the same image file / folder contents.
std::optional<DiscCheck> cachedDiscCheck(const std::string& utf8Path, port::GameVersion v);
// Reads every retail file of the disc (progress 0..1; cancel stops early, returning nullopt).
std::optional<DiscCheck> checkDiscFiles(const std::string& utf8Path, port::GameVersion v,
                                        const std::atomic<bool>* cancel, const std::function<void(float)>& progress);
void saveDiscCheck(const std::string& utf8Path, port::GameVersion v, const DiscCheck& check);
// CF_DISC_CHECK=0 skips the check (test aid); CF_DISC_CHECK=force ignores the cache.
bool discCheckEnabled();
bool discCheckForced();

}  // namespace setup
